//! The project manifest, `pyfun.toml` (`DESIGN.md` §6.2), and the vendored
//! façades it describes.
//!
//! A manifest marks a project root and lists its **façade** dependencies: pip
//! distributions that ship typed `extern` declarations as `.pyfun` files.
//! `pyfun add` installs one, copies its `.pyfun` files into
//! `<root>/.pyfun/facades/<dist>/`, and records the installed version here;
//! `import Name` then resolves a module from a sibling file first and from the
//! vendored façades second ([`super::locate_module`]). Compiling needs neither
//! Python nor the network, since everything it reads is inside the project.
//!
//! The crate takes no dependencies, so this reads and edits only the small
//! subset of TOML a manifest uses: `[table]` headers and `key = "string"`
//! lines. Edits are line-level, so comments and layout survive.

use std::path::{Path, PathBuf};

/// The manifest's file name.
pub const MANIFEST: &str = "pyfun.toml";

/// Where vendored façades live, relative to the project root.
pub const FACADES: &str = ".pyfun/facades";

/// The nearest directory at or above `start` that holds a `pyfun.toml`.
pub fn find_root(start: &Path) -> Option<PathBuf> {
    let mut dir = Some(start);
    while let Some(d) = dir {
        if d.join(MANIFEST).is_file() {
            return Some(d.to_path_buf());
        }
        dir = d.parent();
    }
    None
}

/// Each vendored façade's directory under `root`, in name order.
pub fn facade_dirs(root: &Path) -> Vec<PathBuf> {
    let Ok(entries) = std::fs::read_dir(root.join(FACADES)) else {
        return Vec::new();
    };
    let mut dirs: Vec<PathBuf> = entries
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.is_dir())
        .collect();
    dirs.sort();
    dirs
}

/// A new manifest for a project called `name`.
pub fn new_manifest(name: &str) -> String {
    format!("[project]\nname = \"{name}\"\n\n[dependencies]\n")
}

/// The `key = "value"` entries of `[table]`, in file order.
pub fn table(text: &str, table: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut inside = false;
    for line in text.lines() {
        let line = line.trim();
        if let Some(header) = header_of(line) {
            inside = header == table;
            continue;
        }
        if inside && let Some((key, value)) = entry_of(line) {
            out.push((key, value));
        }
    }
    out
}

/// `text` with `[table]`'s `key` set to `value`: an existing entry is replaced in
/// place, a new one goes after the table's last entry, and a missing table is
/// appended. Every other line is kept as it was.
pub fn set(text: &str, table: &str, key: &str, value: &str) -> String {
    let entry = format!("{key} = \"{}\"", escape(value));
    let lines: Vec<&str> = text.lines().collect();
    let mut inside = false;
    let mut table_end = None; // index after the table's last entry
    for (i, raw) in lines.iter().enumerate() {
        let line = raw.trim();
        if let Some(header) = header_of(line) {
            inside = header == table;
            if inside {
                table_end = Some(i + 1);
            }
            continue;
        }
        if inside {
            if let Some((k, _)) = entry_of(line)
                && k == key
            {
                let mut out: Vec<String> = lines.iter().map(|l| l.to_string()).collect();
                out[i] = entry;
                return join(out);
            }
            if !line.is_empty() && !line.starts_with('#') {
                table_end = Some(i + 1);
            }
        }
    }
    let mut out: Vec<String> = lines.iter().map(|l| l.to_string()).collect();
    match table_end {
        Some(at) => out.insert(at, entry),
        None => {
            if out.last().is_some_and(|l| !l.trim().is_empty()) {
                out.push(String::new());
            }
            out.push(format!("[{table}]"));
            out.push(entry);
        }
    }
    join(out)
}

/// `text` without `[table]`'s `key` entry (unchanged when there is none), and
/// whether an entry was removed.
pub fn remove(text: &str, table: &str, key: &str) -> (String, bool) {
    let mut inside = false;
    let mut removed = false;
    let mut out = Vec::new();
    for raw in text.lines() {
        let line = raw.trim();
        if let Some(header) = header_of(line) {
            inside = header == table;
        } else if inside
            && let Some((k, _)) = entry_of(line)
            && normalize_dist(&k) == normalize_dist(key)
        {
            removed = true;
            continue;
        }
        out.push(raw.to_string());
    }
    (join(out), removed)
}

/// The normalized name of a distribution (PEP 503): lowercase, runs of
/// `-`, `_` and `.` folded to `-`. Used for the façade's directory.
pub fn normalize_dist(name: &str) -> String {
    let mut out = String::new();
    let mut sep = false;
    for c in name.chars() {
        if matches!(c, '-' | '_' | '.') {
            sep = true;
        } else {
            if sep && !out.is_empty() {
                out.push('-');
            }
            sep = false;
            out.push(c.to_ascii_lowercase());
        }
    }
    out
}

fn header_of(line: &str) -> Option<&str> {
    let inner = line.strip_prefix('[')?.strip_suffix(']')?;
    Some(inner.trim())
}

fn entry_of(line: &str) -> Option<(String, String)> {
    if line.starts_with('#') {
        return None;
    }
    let (key, value) = line.split_once('=')?;
    let key = key.trim().trim_matches('"').to_string();
    let value = value.trim();
    let value = value.split_once(" #").map_or(value, |(v, _)| v).trim();
    let unquoted = value.strip_prefix('"')?.strip_suffix('"')?;
    Some((key, unquoted.replace("\\\"", "\"").replace("\\\\", "\\")))
}

fn escape(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

fn join(lines: Vec<String>) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_a_table() {
        let text = "[project]\nname = \"demo\"\n\n[dependencies]\n# the façades\npyfun-textwrap = \"0.1.0\"\n";
        assert_eq!(
            table(text, "dependencies"),
            vec![("pyfun-textwrap".to_string(), "0.1.0".to_string())]
        );
        assert_eq!(table(text, "project")[0].1, "demo");
    }

    #[test]
    fn set_replaces_appends_and_creates() {
        let text = new_manifest("demo");
        let text = set(&text, "dependencies", "a", "1.0");
        let text = set(&text, "dependencies", "b", "2.0");
        let text = set(&text, "dependencies", "a", "1.1");
        assert_eq!(
            table(&text, "dependencies"),
            vec![
                ("a".to_string(), "1.1".to_string()),
                ("b".to_string(), "2.0".to_string())
            ]
        );
        let bare = set("[project]\nname = \"x\"\n", "dependencies", "c", "3");
        assert_eq!(table(&bare, "dependencies")[0].0, "c");
        // Comments and other tables survive an edit.
        let commented = set("# top\n[project]\nname = \"x\"\n", "project", "name", "y");
        assert!(commented.starts_with("# top\n"));
        assert_eq!(table(&commented, "project")[0].1, "y");
    }

    #[test]
    fn remove_drops_one_entry_by_normalized_name() {
        let text = set(&new_manifest("demo"), "dependencies", "Pyfun_Text", "1");
        let text = set(&text, "dependencies", "other", "2");
        let (text, removed) = remove(&text, "dependencies", "pyfun-text");
        assert!(removed);
        assert_eq!(
            table(&text, "dependencies"),
            vec![("other".to_string(), "2".to_string())]
        );
        assert!(!remove(&text, "dependencies", "absent").1);
    }

    #[test]
    fn normalizes_distribution_names() {
        assert_eq!(normalize_dist("Pyfun_Text.Wrap"), "pyfun-text-wrap");
        assert_eq!(normalize_dist("pyfun--x"), "pyfun-x");
    }

    #[test]
    fn finds_the_root_and_its_facades() {
        let root = std::env::temp_dir().join(format!("pyfun_manifest_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("src/deep")).unwrap();
        std::fs::create_dir_all(root.join(FACADES).join("pyfun-b")).unwrap();
        std::fs::create_dir_all(root.join(FACADES).join("pyfun-a")).unwrap();
        std::fs::write(root.join(MANIFEST), new_manifest("demo")).unwrap();
        assert_eq!(
            find_root(&root.join("src/deep")).as_deref(),
            Some(root.as_path())
        );
        let names: Vec<_> = facade_dirs(&root)
            .iter()
            .map(|p| p.file_name().unwrap().to_string_lossy().to_string())
            .collect();
        assert_eq!(names, ["pyfun-a", "pyfun-b"]);
        let _ = std::fs::remove_dir_all(&root);
    }
}
//! `pyfun add`, `pyfun install` and `pyfun remove`: façade dependencies
//! (`DESIGN.md` §6.2).
//!
//! A façade is an ordinary pip distribution that ships typed `extern`
//! declarations as `.pyfun` files. `add` installs it with the environment's own
//! installer (`uv pip` when `uv` is on PATH, else `python -m pip`), copies its
//! `.pyfun` files into `<root>/.pyfun/facades/<dist>/`, and records the installed
//! version in `pyfun.toml`; `install` does the same for every dependency the
//! manifest lists, pinned to its recorded version. The compiler reads only the
//! vendored copies, so checking and compiling stay offline.

use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

use pyfun::project::manifest;

/// `pyfun add <requirement>...`
pub fn add(specs: &[String]) -> ExitCode {
    if specs.is_empty() {
        return fail("`add` needs a package, e.g. `pyfun add pyfun-textwrap`");
    }
    let root = match project_root(true) {
        Ok(root) => root,
        Err(msg) => return fail(&msg),
    };
    for spec in specs {
        let dist = match dist_name(spec) {
            Ok(dist) => dist,
            Err(msg) => return fail(&msg),
        };
        if let Err(msg) = install_and_vendor(&root, spec, &dist) {
            return fail(&msg);
        }
    }
    ExitCode::SUCCESS
}

/// `pyfun install`: every dependency in `pyfun.toml`, at its recorded version.
pub fn install() -> ExitCode {
    let root = match project_root(false) {
        Ok(root) => root,
        Err(msg) => return fail(&msg),
    };
    let text = std::fs::read_to_string(root.join(manifest::MANIFEST)).unwrap_or_default();
    let deps = manifest::table(&text, "dependencies");
    if deps.is_empty() {
        println!("no dependencies in {}", manifest::MANIFEST);
        return ExitCode::SUCCESS;
    }
    for (dist, version) in deps {
        let spec = if version.is_empty() {
            dist.clone()
        } else {
            format!("{dist}=={version}")
        };
        if let Err(msg) = install_and_vendor(&root, &spec, &dist) {
            return fail(&msg);
        }
    }
    ExitCode::SUCCESS
}

/// `pyfun remove <package>...`: drop each from `pyfun.toml`, delete its vendored
/// façade, and uninstall it from the environment.
pub fn remove(dists: &[String]) -> ExitCode {
    if dists.is_empty() {
        return fail("`remove` needs a package name");
    }
    let root = match project_root(false) {
        Ok(root) => root,
        Err(msg) => return fail(&msg),
    };
    let manifest_path = root.join(manifest::MANIFEST);
    let mut text = std::fs::read_to_string(&manifest_path).unwrap_or_default();
    for dist in dists {
        let (updated, removed) = manifest::remove(&text, "dependencies", dist);
        if !removed {
            return fail(&format!(
                "`{dist}` is not a dependency in {}",
                manifest::MANIFEST
            ));
        }
        text = updated;
        let vendored = root
            .join(manifest::FACADES)
            .join(manifest::normalize_dist(dist));
        let _ = std::fs::remove_dir_all(&vendored);
        if let Some(python) = crate::python_cmd() {
            let uv = Command::new("uv").arg("--version").output().is_ok();
            let _ = if uv {
                Command::new("uv")
                    .args(["pip", "uninstall", "--python", &python, dist])
                    .status()
            } else {
                Command::new(&python)
                    .args(["-m", "pip", "uninstall", "-y", dist])
                    .status()
            };
        }
        println!("removed {dist}");
    }
    if let Err(e) = std::fs::write(&manifest_path, text) {
        return fail(&format!("cannot write {}: {e}", manifest_path.display()));
    }
    ExitCode::SUCCESS
}

/// The project root: the nearest `pyfun.toml` at or above the working
/// directory. `add` creates one in the working directory when there is none.
fn project_root(create: bool) -> Result<PathBuf, String> {
    let cwd =
        std::env::current_dir().map_err(|e| format!("cannot read the working directory: {e}"))?;
    if let Some(root) = manifest::find_root(&cwd) {
        return Ok(root);
    }
    if !create {
        return Err(format!(
            "no {} here or in any parent directory (`pyfun add <package>` creates one)",
            manifest::MANIFEST
        ));
    }
    let name = cwd
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| "project".to_string());
    std::fs::write(cwd.join(manifest::MANIFEST), manifest::new_manifest(&name))
        .map_err(|e| format!("cannot write {}: {e}", manifest::MANIFEST))?;
    println!("created {}", manifest::MANIFEST);
    Ok(cwd)
}

/// The distribution a requirement names. A name with an optional version
/// specifier is read directly; a local directory is read from its
/// `pyproject.toml`'s `[project] name`.
fn dist_name(spec: &str) -> Result<String, String> {
    let path = Path::new(spec);
    if path.is_dir() {
        let text = std::fs::read_to_string(path.join("pyproject.toml"))
            .map_err(|_| format!("`{spec}` is a directory with no pyproject.toml"))?;
        return manifest::table(&text, "project")
            .into_iter()
            .find(|(k, _)| k == "name")
            .map(|(_, v)| v)
            .ok_or_else(|| format!("`{spec}/pyproject.toml` has no [project] name"));
    }
    let end = spec
        .find(['=', '<', '>', '!', '~', ';', '[', ' ', '@'])
        .unwrap_or(spec.len());
    let name = spec[..end].trim();
    if name.is_empty() {
        return Err(format!("cannot read a package name from `{spec}`"));
    }
    Ok(name.to_string())
}

fn install_and_vendor(root: &Path, spec: &str, dist: &str) -> Result<(), String> {
    let python = crate::python_cmd().ok_or("no Python interpreter found (set PYFUN_PYTHON)")?;
    run_installer(&python, spec)?;
    let (version, files) = facade_files(&python, dist)?;
    if files.is_empty() {
