from pathlib import Path
from collections import defaultdict
refs={str(p):[(i+1,s.strip()) for i,s in enumerate(p.read_text().splitlines()) if s.strip()] for p in Path('/reference/src').rglob('*') if p.suffix in ('.rs','.js')}
index=defaultdict(list)
k=6
for p,ls in refs.items():
 for i in range(len(ls)-k+1): index[tuple(s for _,s in ls[i:i+k])].append((p,i))
matches=[]
for p in Path('/workspace/src').glob('*.rs'):
 ls=[(i+1,s.strip()) for i,s in enumerate(p.read_text().splitlines()) if s.strip()]
 i=0
 while i<=len(ls)-k:
  best=(0,None,None)
  for rp,ri in index.get(tuple(s for _,s in ls[i:i+k]),[]):
   rls=refs[rp];j=k
